1	// The presentation overlay script — the one whose output the owner looks at.
2	// The 3-panel debug view in measure_vessels.py is deliberately NOT in scope: it
3	// dims the original and uses red for arteries, which is fine for a QA render and
4	// wrong for the presentation figure.
5	const PRESENTATION = 'analysis/annotate_overlays.py';
6	
7	// An (r, g, b) or (r, g, b, a) literal — the only way a drawn colour is spelled
8	// in this script (PIL fill=/np.array colours).
9	const TUPLE = /\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*(?:,\s*\d{1,3}\s*)?\)/g;
10	
11	// Red-dominant = bright red channel that clearly beats BOTH others. Magenta
12	// (255, 0, 255) and the yellow label colour (255, 235, 60) stay legal: they read
13	// against the red signal because blue resp. green carries them.
14	const MARGIN = 60;
15	const isRedDominant = (r, g, b) => r >= 128 && r - g >= MARGIN && r - b >= MARGIN;
16	
17	const rule = {
18	  id: 'overlay-color-contrast',
19	  severity: 'blocking',
20	  description: 'Presentation overlay marks must not be red-dominant',
21	  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
22	  why: 'the gP-CD31 signal being measured IS red — a red outline, arrow or ring vanishes on the very vessels it is supposed to mark',
23	
24	  run(ctx) {
25	    const text = ctx.read(PRESENTATION);
26	    if (text === null) return [];
27	    const out = [];
28	    text.split('\n').forEach((line, i) => {
29	      // A comment or a docstring line describes a colour, it doesn't draw one.
30	      if (line.trim().startsWith('#')) return;
31	      for (const m of line.matchAll(TUPLE)) {
32	        const [r, g, b] = [m[1], m[2], m[3]].map(Number);
33	        if (!isRedDominant(r, g, b)) continue;
34	        out.push({
35	          rule: rule.id,
36	          severity: rule.severity,
37	          file: PRESENTATION,
38	          line: i + 1,
39	          what: `overlay colour (${r}, ${g}, ${b}) is red-dominant`,
40	          why: rule.why,
