1	// Every render the pipeline produces is written into a directory the script
2	// creates for itself (measure_vessels.py --overlays -> analysis/overlays/,
3	// annotate_overlays.py -> analysis/annotated/). Those directories are gitignored,
4	// which is what makes "regenerate, never commit" hold under a `git add -A` or an
5	// agent staging a whole directory.
6	//
7	// Sibling of rendered-overlays-untracked, from the other side: that rule fires once
8	// a render is already tracked (the damage), this one keeps the ignore entry that
9	// stops it getting there. A newly added output directory is the real gap — it is
10	// gitignored only if someone remembers, and nothing said so until now.
11	//
12	// Parse rather than grep: an output directory is one the script actually creates
13	// (`os.makedirs(...)`), resolved through the script's own `HERE` constant, with
14	// comments and string literals handled — a path mentioned in a docstring is not a
15	// directory anything writes to.
16	const SHARED = '.claudinite/shared/';        // read-only mounted canon
17	const HERE_DEF = /^\s*HERE\s*=\s*os\.path\.dirname\(\s*os\.path\.abspath\(\s*__file__\s*\)\s*\)/m;
18	// NAME = os.path.join(HERE, 'annotated')  /  os.path.join(HERE, 'a', 'b')
19	const JOIN = /(?:^|[^\w.])([A-Za-z_]\w*)\s*=\s*os\.path\.join\(\s*HERE\s*,\s*((?:'[^']*'|"[^"]*")(?:\s*,\s*(?:'[^']*'|"[^"]*"))*)\s*\)/g;
20	const MAKEDIRS = /os\.makedirs\(\s*([A-Za-z_]\w*)\b/g;
21	const PARTS = /'([^']*)'|"([^"]*)"/g;
22	
23	// Comments stripped, string literals kept: the joined path segments ARE literals,
24	// so this only removes `#` runs that are not inside a string.
25	function uncomment(text) {
