// this session has no working raw GitHub REST token (GITHUB_TOKEN here is a
// placeholder — MCP tools are the only sanctioned GitHub channel). This computes
// exactly what convergeItem() would do so the session can perform the same
// operations through mcp__github__ tools instead.
import { convergeItem, refusal, OUTCOMES, convergeComment, recordLine } from
  '/home/user/VascularColoring/.claudinite/shared/packs/claudinite-tasks/queue/converge-item.mjs';
import { parseWorkItemBody } from '/home/user/VascularColoring/.claudinite/shared/packs/claudinite-tasks/queue/work-item.mjs';

const item = {
  number: 258,
  title: '[claudinite-work] claudinite-growth/prose-to-checks-sweep',
  body: '.claudinite/shared/packs/claudinite-growth/tasks/prose-to-checks-sweep/task.md\n\nExecute the Claudinite task above.\n\n### Context\n\n- Pack paths to sweep (work ONLY these; never a read-only mounted canon pack under .claudinite/shared/): .claudinite/local/packs.\n',
  state: 'open',
  labels: [{ name: 'task:agent' }],
};

console.log('refusal:', refusal(item, 258));
console.log('parseWorkItemBody:', JSON.stringify(parseWorkItemBody(item.body)));

const calls = [];
const gh = async (path, opts = {}) => {
  calls.push({ path, method: opts.method ?? 'GET', body: opts.body });
  // readIssue is the only read; return the item itself.
  if (opts.method === undefined || opts.method === 'GET') return { status: 200, json: item };
  return { status: opts.method === 'POST' && path.endsWith('/comments') ? 201 : 200, json: {} };
};
const api = await import('/home/user/VascularColoring/.claudinite/shared/packs/claudinite-tasks/github.mjs');

const plan = { issue: 258, outcome: 'approval', pr: 262, summary: 'Converted the UNCALIBRATED-reason rule to a check (uncalibrated-reason-required), the one solid always-testable candidate found under .claudinite/local/packs. See-it-fail fixture added (pack.test.mjs: 25/25 passing), world sweep clean (0 blocking).' };
const res = await convergeItem(api, gh, 'missingbulb/VascularColoring', plan);
console.log('result:', JSON.stringify(res, null, 2));
console.log('calls:');
for (const c of calls) console.log(' ', c.method, c.path, c.body ? JSON.stringify(c.body) : '');

